import java.util.*;
import java.util.stream.*;
// BAD
public enum BadFruit {
    APPLE("apple"),
    ORANGE("orange"),
    BANANA("banana"),
    KIWI("kiwi");

    private final String name;

    BadFruit(String name) { this.name = name; }
    @Override public String toString() { return name; }
    public static Optional<BadFruit> fromString(String name) {
        return Stream.of(values()).filter(v -> v.toString().equals(name)).findAny(); // bad 1: iterates for every call, O(n) access time
    }
    public static Optional<BadFruit> fromName(String name) {
        return Arrays.stream(BadFruit.values()).filter(f -> f.toString().equals(name)).findFirst(); // bad 2: iterates for every call, O(n) access time
    }
}

// Issue #708: missing case
class BadFruitHelper {
    BadFruit toBadFruit(String name) {
        return Arrays.stream(BadFruit.values()).filter(v -> v.toString().equals(name)).findFirst().orElse(null); // bad 3: iterates for every call
    }
}

class BadClass {
    public static BadClass[] values() { return null; }
}

class BadClassHelper {
    BadClass toBadClass(String type) {
        return Arrays.stream(BadClass.values()) // ok, not a predefined method, we don't know the implementation
		.filter(k -> k.value().equals(type)).findFirst().orElse(null);
    }
}

import java.util.*;
import java.util.stream.*;
import static java.util.stream.Collectors.toMap;
// GOOD
enum Fruit {
    APPLE("apple"),
    ORANGE("orange"),
    BANANA("banana"),
    KIWI("kiwi");

    private static final Map<String, Fruit> nameToValue =
            Stream.of(values()).collect(toMap(Object::toString, v -> v));
    private final String name;

    Fruit(String name) { this.name = name; }
    @Override public String toString() { return name; }
    public static Optional<Fruit> fromString(String name) {
        return Optional.ofNullable(nameToValue.get(name)); // good, get from Map, O(1) access time
    }
}
